package vn.edu.eaut.lab5.ui;
import vn.edu.eaut.lab5.bus.TaiKhoanBUS;import vn.edu.eaut.lab5.model.TaiKhoan;import javax.swing.*;import java.awt.*;
public class LoginFrame extends JFrame {private final TaiKhoanBUS bus=new TaiKhoanBUS();private final JTextField user=new JTextField();private final JPasswordField pass=new JPasswordField();private final JButton login=new JButton("Đăng nhập");
 public LoginFrame(){setTitle("MiniShop - Đăng nhập");setSize(380,210);setDefaultCloseOperation(EXIT_ON_CLOSE);setLocationRelativeTo(null);JPanel f=new JPanel(new GridLayout(3,2,8,8));f.setBorder(BorderFactory.createEmptyBorder(20,20,20,20));f.add(new JLabel("Tài khoản:"));f.add(user);f.add(new JLabel("Mật khẩu:"));f.add(pass);f.add(new JLabel());f.add(login);add(f);login.addActionListener(e->doLogin());pass.addActionListener(e->doLogin());}
 private void doLogin(){login.setEnabled(false);new SwingWorker<TaiKhoan,Void>(){protected TaiKhoan doInBackground()throws Exception{return bus.login(user.getText(),new String(pass.getPassword()));}protected void done(){try{TaiKhoan x=get();if(x==null)throw new IllegalArgumentException("Tài khoản hoặc mật khẩu không đúng");dispose();new MainFrame(x).setVisible(true);}catch(Exception e){Throwable c=e.getCause()==null?e:e.getCause();JOptionPane.showMessageDialog(LoginFrame.this,c.getMessage(),"Đăng nhập thất bại",JOptionPane.ERROR_MESSAGE);login.setEnabled(true);}}}.execute();}
}
